import * as React from "react";

export type ServerStackIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function ServerStackIcon({ size = 20, ...props }: ServerStackIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <rect x="4" y="4" width="16" height="5" rx="1" /><rect x="4" y="11" width="16" height="5" rx="1" /><circle cx="7" cy="6.5" r="0.8" /><circle cx="7" cy="13.5" r="0.8" />
    </svg>
  );
}
